import React, { useState, useEffect, useRef, useLayoutEffect } from 'react';
import axios from 'axios';
import './Dashboard.css';
import Logo from '../components/Logo';
import Materials from './components/Materials';
import Examinations from './components/Examinations';
import Plans from './components/Plans';
import DailyTasks from './components/DailyTasks';
import AdminPanel from './components/AdminPanel';
import CuratorPanel from './components/CuratorPanel';
import MyCuratorPlans from './components/MyCuratorPlans';
import Tests from './components/Tests';
import Flashcards from './components/Flashcards';
import NotifyButton from './components/NotifyButton';
import ThemeToggle from '../components/ThemeToggle';
import { AnnouncementsBar } from './components/Announcements';
import { API, api, errorText } from '../api';
import { formatKkDate, capitalize } from '../utils/kkDate';
import { prettyPhone } from '../utils/phone';
import { LuBookOpen, LuBrain, LuCalendarDays, LuClapperboard, LuFileQuestion, LuFlame, LuListChecks, LuPencil, LuSettings2, LuTarget, LuUsers } from 'react-icons/lu';

const ROLE_LABELS = {
  admin: 'Админ',
  curator: 'Куратор',
  student: 'Оқушы'
};

const initials = (name = '') =>
  name.split(' ').filter(Boolean).slice(0, 2).map((w) => w[0]).join('').toUpperCase();

const greeting = () => {
  const hour = new Date().getHours();
  if (hour < 12) return 'Қайырлы таң';
  if (hour < 18) return 'Қайырлы күн';
  return 'Қайырлы кеш';
};

export default function Dashboard({ student, onLogout, onProfileUpdate }) {
  const [activeTab, setActiveTab] = useState('materials');
  const [role, setRole] = useState(student.role || (student.student_number === 'admin' ? 'admin' : 'student'));
  const [indicator, setIndicator] = useState({ left: 0, width: 0 });
  const [stats, setStats] = useState(null);
  const [editingName, setEditingName] = useState(false);
  const [nameDraft, setNameDraft] = useState('');
  const [nameError, setNameError] = useState('');
  const [savingName, setSavingName] = useState(false);
  const tabRefs = useRef({});
  const isAdmin = role === 'admin';
  const isCurator = role === 'curator';

  // Админ рөлді кез келген уақытта өзгерте алады, сондықтан профильден жаңартамыз
  useEffect(() => {
    const token = localStorage.getItem('token');
    axios.get(`${API}/api/profile`, {
      headers: { Authorization: `Bearer ${token}` }
    })
      .then(({ data }) => {
        const freshRole = data.student_number === 'admin' ? 'admin' : (data.role || 'student');
        setRole(freshRole);
        // Аты-жөні басқа құрылғыда өзгертілген болуы мүмкін, сондықтан оны да жаңартамыз
        onProfileUpdate({ role: freshRole, name: data.name });
      })
      .catch((error) => console.error('Профиль алу қатесі:', error));
  }, []);

  // Серия: бөлім ауысқанда жаңарады (тапсырма орындалса бірден көрінеді)
  useEffect(() => {
    api.get('/api/me/stats').then(setStats).catch(() => {});
  }, [activeTab]);

  const tabs = [
    { id: 'materials', icon: <LuBookOpen />, label: 'Материалдар' },
    { id: 'examinations', icon: <LuClapperboard />, label: 'Нұсқа талдаулар' },
    { id: 'plans', icon: <LuCalendarDays />, label: 'Жоспар' },
    { id: 'daily', icon: <LuListChecks />, label: 'Бүгінгі тапсырмалар' },
    { id: 'tests', icon: <LuFileQuestion />, label: 'Тесттер' },
    { id: 'cards', icon: <LuBrain />, label: 'Карточкалар' },
    role === 'student' && { id: 'curator-plans', icon: <LuTarget />, label: 'Куратор жоспары' },
    (isCurator || isAdmin) && { id: 'curator', icon: <LuUsers />, label: 'Менің оқушыларым' },
    isAdmin && { id: 'admin', icon: <LuSettings2 />, label: 'Админ панелі' }
  ].filter(Boolean);

  // Белсенді таб астындағы сырғымалы сызық
  useLayoutEffect(() => {
    const updateIndicator = () => {
      const el = tabRefs.current[activeTab];
      if (el) setIndicator({ left: el.offsetLeft, width: el.offsetWidth });
    };
    updateIndicator();
    window.addEventListener('resize', updateIndicator);
    return () => window.removeEventListener('resize', updateIndicator);
  }, [activeTab, role]);

  const selectTab = (id) => {
    setActiveTab(id);
    tabRefs.current[id]?.scrollIntoView({ behavior: 'smooth', block: 'nearest', inline: 'center' });
  };

  const openNameEditor = () => {
    setNameDraft(student.name || '');
    setNameError('');
    setEditingName(true);
  };

  const saveName = async (e) => {
    e.preventDefault();
    const name = nameDraft.trim().replace(/\s+/g, ' ');
    if (name.length < 2) {
      setNameError('Аты-жөніңізді толық жазыңыз');
      return;
    }
    setSavingName(true);
    try {
      const data = await api.patch('/api/profile', { name });
      onProfileUpdate({ name: data.name });
      setEditingName(false);
    } catch (error) {
      setNameError(errorText(error, 'Сақтау мүмкін болмады. Қайталап көріңіз'));
    } finally {
      setSavingName(false);
    }
  };

  const firstName = student.name?.split(' ')[0] || '';
  const today = capitalize(formatKkDate(new Date(), { weekday: 'long' }));

  return (
    <div className="dashboard">
      <header className="dashboard-header">
        <div className="header-inner">
          <Logo size="sm" className="header-logo" />

          <div className="user-chip">
            <ThemeToggle />
            <NotifyButton />
            <button type="button" className="profile-btn" onClick={openNameEditor} title="Аты-жөнін өзгерту">
              <span className="avatar">{initials(student.name)}</span>
              <span className="user-meta">
                <strong>{student.name}<LuPencil className="edit-ic" /></strong>
                <span>
                  <span className={`role-dot role-${role}`} />
                  {ROLE_LABELS[role]} · {prettyPhone(student.phone || student.student_number)}
                </span>
              </span>
            </button>
            <button onClick={onLogout} className="logout-btn" title="Шығу">
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                <path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4" />
                <polyline points="16 17 21 12 16 7" />
                <line x1="21" y1="12" x2="9" y2="12" />
              </svg>
              <span>Шығу</span>
            </button>
          </div>
        </div>

        <nav className="dashboard-nav">
          <div className="nav-track">
            {tabs.map((tab) => (
              <button
                key={tab.id}
                ref={(el) => { tabRefs.current[tab.id] = el; }}
                className={activeTab === tab.id ? 'active' : ''}
                onClick={() => selectTab(tab.id)}
              >
                <span className="tab-icon">{tab.icon}</span>
                {tab.label}
              </button>
            ))}
            <span className="nav-indicator" style={{ transform: `translateX(${indicator.left}px)`, width: indicator.width }} />
          </div>
        </nav>
      </header>

      {editingName && (
        <div className="name-modal" onClick={() => !savingName && setEditingName(false)}>
          <form className="name-box" onSubmit={saveName} onClick={(e) => e.stopPropagation()}>
            <h3>Аты-жөнін өзгерту</h3>
            <p>Куратор мен рейтингте осы атпен көрінесіз.</p>
            <input
              value={nameDraft}
              onChange={(e) => { setNameDraft(e.target.value); setNameError(''); }}
              onKeyDown={(e) => e.key === 'Escape' && setEditingName(false)}
              placeholder="Мысалы: Майкл Джексон"
              maxLength={100}
              autoFocus
              onFocus={(e) => e.target.select()}
            />
            {nameError && <div className="name-error">{nameError}</div>}
            <div className="name-actions">
              <button type="button" className="ghost" onClick={() => setEditingName(false)} disabled={savingName}>Болдырмау</button>
              <button type="submit" disabled={savingName || nameDraft.trim() === (student.name || '')}>
                {savingName ? 'Сақталуда…' : 'Сақтау'}
              </button>
            </div>
          </form>
        </div>
      )}

      <section className="welcome">
        <div className="welcome-inner">
          <div>
            <p className="welcome-date">{today}</p>
            <h1>{greeting()}, {firstName}!</h1>
            <p className="welcome-sub">Бүгін де бір қадам алға. Жоспарыңды орында, нәтижеңді көр.</p>
            {stats && (
              <div className={`streak-chip ${stats.streak >= 3 ? 'hot' : ''}`} title={`Ең ұзақ серия: ${stats.best_streak} күн`}>
                <LuFlame className="flame" />
                {stats.streak > 0
                  ? <>{stats.streak} күн қатарынан!{!stats.done_today && ' Бүгін де бір тапсырма орында'}</>
                  : 'Бүгін бір тапсырма орындап, серияны баста!'}
              </div>
            )}
          </div>
          <div className="welcome-art" aria-hidden="true">
            <span>∑</span><span>π</span><span>√</span>
          </div>
        </div>
      </section>

      <AnnouncementsBar />

      <main className="dashboard-content" key={activeTab}>
        {activeTab === 'materials' && <Materials isAdmin={isAdmin} />}
        {activeTab === 'examinations' && <Examinations isAdmin={isAdmin} />}
        {activeTab === 'plans' && <Plans />}
        {activeTab === 'daily' && <DailyTasks />}
        {activeTab === 'curator-plans' && <MyCuratorPlans />}
        {activeTab === 'tests' && <Tests />}
        {activeTab === 'cards' && <Flashcards />}
        {activeTab === 'curator' && (isCurator || isAdmin) && <CuratorPanel />}
        {activeTab === 'admin' && isAdmin && <AdminPanel />}
      </main>
    </div>
  );
}
